import { globSync } from 'node:fs';
import { sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, it } from 'vitest';
import { loadSource } from './docs.ts';

const DOCS = fileURLToPath(new URL('..', import.meta.url));
const BUNDLE = fileURLToPath(new URL('../../packages/cli/dist/docs', import.meta.url));

it('bundles every source page and the CLI reference into the built CLI, and nothing else', () => {
  const bundled = globSync('**/*.md', { cwd: BUNDLE }).map((file) => file.replaceAll(sep, '/'));
  // docs/cli/ is generated by the docs build; the bundle writes the reference from the bin itself.
  const source = loadSource(DOCS)
    .map((page) => `${page.path}.md`)
    .filter((file) => !file.startsWith('cli/'));
  expect(source).toContain('index.md');
  const reference = bundled.filter((file) => file.startsWith('cli/'));
  expect(reference).toContain('cli/index.md');
  expect(bundled.toSorted()).toEqual([...source, ...reference].toSorted());
});
